pub fn digitsum(n: i64) -> i64 {
    let mut total = 0;
    for i in 0..n {
        let mut x = i;
        while x > 1 {
            total += x % 10;
            x /= 10;
        }
    }
    total
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_digitsum() {
        assert_eq!(digitsum(10), 45);
        assert_eq!(digitsum(100), 900);
    }
}
